#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"

/* Include the Exo-generated kernel header. */
#include "generated/trisolv/trisolv.h"


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;
      for (j = 0; j <= i; j++)
	L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import divide_loop, unroll_loop, simplify, rename

# Block size for the inner j-loop. Kept small to balance code size and ILP.
J_BLOCK: int = 4


@proc
def trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    # Forward substitution for a lower-triangular system L * x = b.
    # Each x[i] depends only on x[0..i-1], so the outer i-loop is inherently
    # sequential; we optimize the inner j-loop and scalar temporaries.
    for i in seq(0, n):
        # Accumulate into a scalar to avoid repeated memory writes to x[i].
        xi: DATA_TYPE
        xi = b[i]

        # Dot product between L[i, 0:i] and x[0:i], keeping xi in a register.
        for j in seq(0, i):
            xi = xi - L[i, j] * x[j]

        # Divide once by the diagonal and write the result back to memory.
        xi = xi / L[i, i]
        x[i] = xi


# Start from the base kernel and apply schedule transformations.
kernel_trisolv_sched = trisolv_base

# Tile the inner j-loop. This improves spatial locality on the L row
# and exposes a fixed-size inner loop to the backend compiler.
kernel_trisolv_sched = divide_loop(
    kernel_trisolv_sched,
    kernel_trisolv_sched.find_loop("j"),
    J_BLOCK,
    ["jo", "ji"],
)

# Fully unroll the fixed-size inner "ji" loop (size == J_BLOCK).
# This removes loop overhead and can help the compiler keep xi in a register.
kernel_trisolv_sched = unroll_loop(
    kernel_trisolv_sched,
    kernel_trisolv_sched.find_loop("ji"),
)

# Simplify after transformations to clean up index arithmetic.
kernel_trisolv_sched = simplify(kernel_trisolv_sched)

# Expose the scheduled kernel under the name expected by the C driver.
kernel_trisolv = rename(kernel_trisolv_sched, "kernel_trisolv")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_trisolv (/*ctxt=*/NULL,
                  n,
                  (DATA_TYPE*)POLYBENCH_ARRAY(L),
                  (DATA_TYPE*)POLYBENCH_ARRAY(x),
                  (DATA_TYPE*)POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
