from __future__ import annotations

# Core Exo imports.
from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.frontend.syntax import *

# Baseline triangular solve kernel: forward substitution on a lower-triangular
# matrix L. This matches the original PolyBench trisolv kernel.
@proc
def kernel_trisolv(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Initialize x[i] with the right-hand side.
        x[i] = b[i]
        # Forward substitution: subtract previously computed components.
        for j in seq(0, i):
            x[i] = x[i] - L[i, j] * x[j]
        # Divide by the diagonal element.
        x[i] = x[i] / L[i, i]


